	for (const id of ["t1-a", "__proto__", "constructor", ""]) {
		const widget = getWidget(id);
		expect(widget).toEqual({ id });
		expect(Object.getPrototypeOf(widget)).toBe(Object.prototype);
		expect(Object.hasOwn(widget, "id")).toBe(true);
	}
