	expect(() => {
		(widget as { id: string }).id = "t4-b";
	}).toThrow(TypeError);
	expect(widget.id).toBe("t4-a");
	expect(getWidget("t4-a").id).toBe("t4-a");
	expect(JSON.stringify(widget)).toBe('{"id":"t4-a"}');
	expect(Object.keys(widget)).toEqual(["id"]);
});

