const widgets = new Map<string, { readonly id: string }>();

export function getWidget(id: string): { readonly id: string } {
	const cached = widgets.get(id);
	if (cached) return cached;

	const widget = {};
	Object.defineProperty(widget, "id", { value: id, enumerable: true, writable: false, configurable: false });
	const created: { readonly id: string } = widget as { readonly id: string };
	widgets.set(id, created);
	return created;
}

const widgets = new Map<string, { readonly id: string }>();

export function getWidget(id: string): { readonly id: string } {
	const cached = widgets.get(id);
	if (cached) return cached;

	const widget: { readonly id: string } = { id };
	// Lock id at runtime: assignments throw in strict mode, so the cached widget always matches its key.
	Object.defineProperty(widget, "id", { writable: false, configurable: false });
	widgets.set(id, widget);
	return widget;
}

